CREATE TABLE IF NOT EXISTS "stock_book_move_t" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "stock_book_move_t_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"source_type" varchar(10) NOT NULL,
	"indent_id" integer NOT NULL,
	"source_record_id" integer NOT NULL,
	"new_record_id" integer,
	"item_id" integer NOT NULL,
	"qty_moved" integer NOT NULL,
	"from_stock_book_master_id" integer,
	"from_page_no" integer,
	"to_stock_book_master_id" integer NOT NULL,
	"to_page_no" integer,
	"moved_date" date NOT NULL,
	"moved_by" integer NOT NULL,
	"remarks" varchar(255),
	"created_by" integer,
	"created_at" timestamp DEFAULT now(),
	"display" varchar(1) DEFAULT 'Y'
);
